-- Manual source receipt only, outside CI. No research-object content fields read.
BEGIN READ ONLY; SET LOCAL ROLE anon; WITH p AS (SELECT id,slug,title,excerpt,author,source,tags,home_hidden,date,modified,created_at,space FROM public.posts WHERE home_hidden=false AND NOT(tags @> ARRAY['טיוטה']) AND NOT(tags @> ARRAY['פורום']) AND source IN ('wordpress','SOD1820','sod1820','source_document','ai','uploaded_file') ORDER BY modified DESC NULLS LAST LIMIT 48), research_count AS (SELECT count(*) AS n FROM public.research_objects WHERE status IN ('approved','canonical')) SELECT jsonb_build_object('research_count',(SELECT n FROM research_count),'research_data',CASE WHEN (SELECT n FROM research_count)=0 THEN '[]'::jsonb ELSE NULL END,'posts_count',(SELECT count(*) FROM p),'posts_data',CASE WHEN (SELECT bool_and(space='core' AND (author IS NULL OR author IN ('','SOD1820','אלון לוי','בדרך לנצח','המערכת','הרב ווינטרוב זצ"ל','הרב לוי סודרי','יניב לוי','יעקב קירש','מדריך לריפוי 10 הספירות','מזכה הרבים','מערכת כי לה׳ המלוכה','נריה דויטש','סוד החשמל','צבי','ציון סיבוני'))) FROM p) THEN (SELECT jsonb_agg(to_jsonb(p)-'space' ORDER BY modified DESC NULLS LAST) FROM p) ELSE NULL END) AS public_only_payload; COMMIT;
